import './style.css'

import estante from '../../img/estante.svg'
import sacola from '../../img/livro.svg'


const icones = [perfil, sacola]

function IconesHeader() {
    return (
        <ul className='icones'>
            {icones.map((icone) => (
                <li className='icone'>
                    <img src={icone}></img>
                </li>
            ))}
        </ul>
    )
}

export default IconesHeader
